	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		BackgroundCheck
	 */
		public BackgroundCheck createBackgroundCheck( CreateBackgroundCheckCommand command ) {

		BackgroundCheck entity = new BackgroundCheck();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setBackgroundCheckId( command.getBackgroundCheckId() );
            entity.setCheckNumber( command.getCheckNumber() );
            entity.setProvider( command.getProvider() );
            entity.setCompletedDate( command.getCompletedDate() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of BackgroundCheck {0} ", entity.toString() );

		return entity;
	}

